function draw(){const r=canvasBox||(canvasBox=canvas.getBoundingClientRect()),dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;if(!W||!H)return;if(canvas.width!==Math.round(W*dpr)||canvas.height!==Math.round(H*dpr)){canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.imageSmoothingEnabled=false;tile=(area==='street'?(W<600?27:32):Math.min(58,Math.max(30,Math.min(W/current().w,H/current().h)*1.45)))*cameraZoom;const mapW=current().w*tile,mapH=current().h*tile;cam.x=mapW<=W?(mapW-W)/2:Math.min(mapW-W,Math.max(0,(player.px+.5)*tile-W/2));cam.y=mapH<=H?(mapH-H)/2:Math.min(mapH-H,Math.max(0,(player.py+.5)*tile-H/2));const autoX=cam.x,autoY=cam.y;cam.x=mapW<=W?(mapW-W)/2:Math.max(0,Math.min(mapW-W,autoX+cameraPan.x));cam.y=mapH<=H?(mapH-H)/2:Math.max(0,Math.min(mapH-H,autoY+cameraPan.y));cameraPan.x=cam.x-autoX;cameraPan.y=cam.y-autoY;rect(0,0,W,H,area==='street'?'#80a577':({home:'#504356',work:'#374b59',school:'#40585a',shop:'#51415f',cafe:'#654b4b',bank:'#34455c',station:'#35324c',coast:'#779eab'}[area]||'#405753'));ctx.save();ctx.translate(-cam.x,-cam.y);
for(let y=Math.max(0,Math.floor(cam.y/tile));y<Math.min(current().h,Math.ceil((cam.y+H)/tile));y++)for(let x=Math.max(0,Math.floor(cam.x/tile));x<Math.min(current().w,Math.ceil((cam.x+W)/tile));x++){let c=area==='street'?((x+y)%2?'#86aa7c':'#8db182'):((x+y)%2?'#c4a884':'#ccb38f');if(area==='street'){if((y>=7&&y<=14)||(x>=10&&x<=19))c='#a8a69a';if(y>=9&&y<=12)c='#6d7e82';if(x>=12&&x<=17)c='#6d7e82';if(x>=31&&x<=33)c='#a8a69a';if(y>=24&&y<=25)c='#a8a69a'}rect(x*tile,y*tile,tile,tile,c);if(area==='street'&&c!=='#6d7e82'&&c!=='#a8a69a'&&(x*17+y*11)%5===0){rect(x*tile+7,y*tile+13,2,4,'#719767');rect(x*tile+10,y*tile+11,2,4,'#719767');if((x+y)%4===0)rect(x*tile+8,y*tile+10,3,2,'#e5bc89')}if(['park','market','square'].includes(area))c=(x+y)%2?'#88ac7f':'#91b387';if(['park','market','square'].includes(area))rect(x*tile,y*tile,tile,tile,c);if(area!=='street'&&!['park','market','square'].includes(area)){rect(x*tile,y*tile,tile,1,'#b59c7d');rect(x*tile,y*tile,1,tile,'#b59c7d')}}
if(area==='street'){for(let x=0;x<32;x+=3)rect(x*tile+8,10.8*tile,tile*1.3,4,'#e7deaa');for(const [x,y]of[[0,0],[10,3],[19,2],[30,4],[1,13],[30,14],[1,21],[12,20],[18,21],[30,21]])tree((x+.5)*tile,(y+.5)*tile);for(let i=0;i<3;i++){rect((10+i)*tile,6*tile,tile-2,13,'#c6a475');rect((10+i)*tile,6*tile+14,4,13,'#776654')}}else if(['park','market','square'].includes(area)){for(const [tx,ty]of[[1,1],[3,2],[10,1],[12,4],[2,7],[9,8]])tree((tx+.5)*tile,(ty+.5)*tile);rect(3*tile,5*tile,7*tile,tile,'#c5b38e');rect(2*tile,4*tile,2*tile,12,'#a5815f');rect(9*tile,6*tile,2*tile,12,'#a5815f')}else{rect(0,0,mapW,14,'#a0b8c6');rect(0,0,12,mapH,'#8aa4b7');rect(5*tile,0,2*tile,10,'#e6e3cf');rect(5*tile,10,2*tile,22,'#9bc1d1');if(area==='home'){rect(5*tile,4*tile,4*tile,3*tile,'#9293b2');rect(5*tile+8,4*tile+8,4*tile-16,3*tile-16,'#a5a4be')}}
if(path.length){for(let i=0;i<path.length;i+=2){const [x,y]=path[i];rect(x*tile+tile/2-2,y*tile+tile/2-2,4,4,'#ffe6a288')}const d=path[path.length-1];rect(d[0]*tile+5,d[1]*tile+5,tile-10,tile-10,'#ffd16680')}
const items=current().objects.filter(o=>(o.x+o.w+2)*tile>=cam.x&&(o.x-2)*tile<=cam.x+W&&(o.y+o.h+2)*tile>=cam.y&&(o.y-3)*tile<=cam.y+H).map(o=>({depth:o.y+o.h,draw:()=>furniture(o)}));items.push({depth:player.py+1,draw:()=>person((player.px+.5)*tile,(player.py+.5)*tile,'#8170c9','Miguel',true)});items.sort((a,b)=>a.depth-b.depth).forEach(o=>o.draw());if(area==='street'){const target=current().objects.find(o=>o.id===nextGoal().id);if(target){const x=(target.x+target.w/2)*tile,y=target.y*tile-24;label('PRÓXIMO PASSO',x,y,'#ffe296',11)}}if(performance.now()<celebrationUntil){for(let i=0;i<9;i++){const a=i*Math.PI*2/9,r=25+(phase%4)*5;rect((player.px+.5)*tile+Math.cos(a)*r,(player.py-.4)*tile+Math.sin(a)*r,4,4,'#ffd166')}}ctx.restore();drawAtmosphere();}
function close(){sound.duck(false);layer.hidden=true;mapOpen=false;view.focus({preventScroll:true});draw()}
function dialog(who,title,body,choices=[]){root.querySelector('#b-toast').hidden=true;releaseHold();path=[];pending=null;player.px=player.x;player.py=player.y;sound.duck(true);if(who!=='RESULTADO')sound.cue(who.includes('CELULAR')?'phone':who.includes('CARTÃO')?'warning':choices.length?'request':'dialog');returnFocus=document.activeElement;root.querySelector('#b-speaker').textContent=who;root.querySelector('#b-title').textContent=title;content.innerHTML=body;options.replaceChildren();for(const choice of choices){const b=document.createElement('button');b.type='button';b.textContent=choice.label;if(choice.primary)b.className='b-primary';if(choice.disabled)b.disabled=true;b.onclick=choice.action;options.append(b)}layer.hidden=false;animateElement(layer.querySelector('.b-dialog'));(options.querySelector('button:not(:disabled)')||closer).focus({preventScroll:true});say(title)}
let engine=null,financial=null;
function pull(s){financial=s;cash=s.cash;reserve=s.reserve;debt=s.debt;notebook=s.assets.includes('laptop');decorateHome();update();draw();root.querySelector('#b-month').textContent='Mês '+s.month+' / 8';}
function phone(){if(!engine){say('Preparando o motor financeiro…');return}dialog('CELULAR · MIGUEL','Sua vida financeira.',`<div class="b-phone-grid"><div><small>Conta</small><strong>${cashFmt(cash)}</strong></div><div><small>Reserva</small><strong>${cashFmt(reserve)}</strong></div><div><small>Limite livre</small><strong>${cashFmt(financial.limit)}</strong></div><div><small>Fatura do mês</small><strong>${cashFmt(financial.bill)}</strong></div></div><p>Bens: ${financial.assets.map(id=>financial.goods.find(p=>p.id===id)?.name||id).join(', ')||'nenhuma compra ainda'}.</p><p>Renda ${cashFmt(financial.salary)} · gastos fixos ${cashFmt(financial.costs)}. Reserva ativa: aporte mensal de 10% do salário bruto; rendimento na virada conforme a v27.7.</p>`,[{label:financial.active?'Pausar aportes automáticos':'Ativar reserva mensal',primary:true,action(){pull(engine.reserve(!financial.active));phone()}},{label:'Resgatar reserva',disabled:reserve<=0,action(){pull(engine.rescue());phone()}},{label:'Resolver fatura atual',disabled:financial.bill<=0,action:()=>invoiceGate(phone)},{label:'Ver compromissos do cartão',action:()=>dialog('CARTÃO','Compras e obrigações.',`<p>Dívida total: <strong>${cashFmt(debt)}</strong>.<br>Fatura atual: ${cashFmt(financial.bill)}.<br>Mínimo: ${cashFmt(financial.minimum)}.<br>Juros de rotativo neste mês: ${cashFmt(financial.interest)}.</p><p>Compras feitas agora entram na próxima fatura. Parcelas em dia e saldo financiado seguem as regras da v27.7.</p>`,[])}]);}

function invoiceGate(back){dialog('CARTÃO · FATURA DO MÊS','Antes da próxima compra.',`<p>Fatura: <strong>${cashFmt(financial.bill)}</strong> · mínimo: ${cashFmt(financial.minimum)}.</p><p>Escolha o pagamento deste ciclo antes de fazer novas compras. O saldo não pago segue as regras de rotativo e atraso da v27.7.</p>`,[{label:'Pagar integral',primary:true,disabled:cash<financial.bill,action(){pull(engine.pay('invoiceFull'));back()}},{label:'Pagar mínimo',disabled:cash<financial.minimum,action(){pull(engine.pay('invoiceMinimum'));back()}},{label:'Deixar sem pagamento neste ciclo',action(){pull(engine.pay('invoiceNoPay'));back()}}]);}

function navigate(id){close();if(area!=='street')change('street');const o=current().objects.find(o=>o.id===id);go(o)}
function step(dir){if(performance.now()<inputBlockedUntil||!layer.hidden||path.length)return;const [dx,dy]={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[dir];walk(player.x+dx,player.y+dy)}
let day=0,energy=100,shifts=0,rested=false,leisureDone=false,errand=false,quizDone=false,celebrationUntil=0;
const days=['Segunda','Terça','Quarta','Sábado','Domingo'];
const districts={tech:['phone','phonePremium','laptop','gamer','headphone','headphoneBasic','gameConsole','drone'],style:['clothesNeed','comfyShoes','premiumShoes','backpack','watch','glasses'],home:['studyKit','desk','bike','dental']};
areas.street.w=48;areas.street.h=32;areas.street.name='Cidade das Possibilidades';
areas.street.objects.push({id:'style',name:'Moda e cuidados',x:35,y:2,w:9,h:4,to:[39,6],kind:'building',color:'#a57693'},{id:'cafe',name:'Café da esquina',x:35,y:10,w:9,h:4,to:[39,14],kind:'building',color:'#b48c64'},{id:'park',name:'Parque · lazer',x:34,y:19,w:10,h:5,to:[38,18],kind:'building',color:'#709b79'},{id:'bank',name:'Banco e planejamento',x:21,y:25,w:9,h:4,to:[25,24],kind:'building',color:'#7285a8'},{id:'bus',name:'Ponto de ônibus',x:16,y:17,w:2,h:2,to:[15,18],kind:'counter'},{id:'leo',name:'Léo · entregas',x:18,y:21,w:1,h:1,to:[18,22],kind:'person'});
for(const [id,name]of [['style','Moda e cuidados'],['cafe','Café da esquina'],['park','Parque da cidade'],['bank','Banco']])areas[id]={w:14,h:10,name,spawn:[6,7],objects:[{id:id+'host',name:{style:'Nina · atendimento',cafe:'Caio · barista',park:'Bia · encontro',bank:'Joana · orientação'}[id],x:6,y:2,w:2,h:2,to:[6,4],kind:'counter'},{id:'exit',name:'Voltar à cidade',x:11,y:7,w:2,h:2,to:[10,7],kind:'door'}]};
function objectDistance(o){const dx=Math.max(o.x-player.x,0,player.x-(o.x+o.w-1)),dy=Math.max(o.y-player.y,0,player.y-(o.y+o.h-1));return Math.hypot(dx,dy)}
function nearest(){return current().objects.filter(o=>objectDistance(o)<=(o.kind==='person'?2.2:1.5)).sort((a,b)=>objectDistance(a)-objectDistance(b))[0]}
function go(o){if((o.kind==='person'||o.kind==='counter')&&objectDistance(o)<=2.2){interact(o);return}const candidates=[];if(o.kind==='person'||o.kind==='counter'){for(let y=o.y-1;y<=o.y+o.h;y++)for(let x=o.x-1;x<=o.x+o.w;x++){if(!pass(x,y))continue;const p=route(x,y);if(p)candidates.push({x,y,n:p.length})}}else candidates.push({x:o.to[0],y:o.to[1],n:0});candidates.sort((a,b)=>a.n-b.n);if(candidates.length)walk(candidates[0].x,candidates[0].y,o);else say('Não há passagem até este local.')}
function nextGoal(){if(!talked)return{title:'Conheça sua cidade: converse com Bia.',id:'bia'};if(!studied)return{title:'Prepare-se na biblioteca. Estudar é gratuito.',id:'school'};if(shifts<3&&day<3)return{title:'Seu turno CLT: vá ao trabalho.',id:'work'};if(!errand)return{title:'Léo precisa de uma orientação na cidade.',id:'leo'};if(!leisureDone)return{title:'Separe um tempo para você no parque.',id:'park'};return{title:day<4?'Volte para casa e descanse para o próximo dia.':'Feche o mês e planeje o próximo capítulo.',id:'home'}}
function update(){root.querySelector('#b-cash').textContent=cashFmt(cash);root.querySelector('#b-time').textContent=days[day]+' · '+String(Math.floor(time/60)).padStart(2,'0')+':'+String(time%60).padStart(2,'0');root.querySelector('#b-place').textContent=areas[area].name;root.querySelector('#b-goal').textContent=nextGoal().title;root.querySelector('#b-compass').textContent=compassBearing();const n=nearest();const interactButton=root.querySelector('#b-interact');if(interactButton.hidden!==!n)interactButton.hidden=!n;root.querySelector('#b-context').textContent=n?'Conversar / usar · '+n.name:'Toque em pessoas ou lugares';root.querySelector('#b-energy').textContent='Disposição '+energy+'%';}
function useEnergy(n){if(energy<n){result('Miguel está cansado. Descanse em casa ou faça uma pausa no parque.','rest');return false}energy-=n;return true}
function workShift(){if(day>2){dialog('LUANA','Hoje é sua folga.',`<p>“Bom descanso, Miguel. Aproveite a cidade e cuide dos seus planos.”</p>`,[]);return}if(rested){result('Seu turno de hoje já terminou. Aproveite o tempo livre.','dialog');return}dialog('LUANA · ROTINA CLT','Um turno, uma decisão.',`<p>Horário de referência: 09h às 18h, com pausa. Salário líquido: ${cashFmt(financial.salary)}; já lançado no início do mês.</p><p>Chegaram duas solicitações: um cliente aguarda uma entrega e há uma divergência no estoque. Como começar?</p>`,[{label:'Conferir a divergência e informar o prazo ao cliente',primary:true,action(){if(!useEnergy(35))return;shifts++;rested=true;time=Math.max(time,1080);result('Você organizou o atendimento e os registros. Turno concluído, sem receber o salário duas vezes. Agora escolha como aproveitar a noite.')}},{label:'Prometer a entrega sem conferir',action(){result('O prazo depende da conferência. Luana sugere verificar o estoque e comunicar uma previsão realista. Tente outra estratégia.','request')}}]);}
function sleep(){dialog('MIGUEL · EM CASA',day<4?'Encerrar o dia?':'Seu mês, suas escolhas.',`<p>${day<4?'O descanso recupera sua disposição e abre o próximo dia. Você pode continuar explorando antes de dormir.':'Você pode fechar o mês ou continuar explorando.'}</p>`,[{label:day<4?'Dormir e começar o próximo dia':'Revisar o fechamento do mês',primary:true,action(){if(day===4){monthEnd();return}day++;time=540;energy=100;rested=false;result(days[day]+': '+(day>2?'dia de folga. O parque e o café estão abertos.':'mais um dia na cidade.'),'rest')}}]);}
function interact(o=nearest()){if(!o||!layer.hidden)return;if(o.id.startsWith('owned-')){result(o.name+' faz parte das suas conquistas. Os compromissos da compra continuam no celular.','dialog');return}if(path.length){pending=o;return}if(o.id==='exit'){change('street');return}if(area==='street'&&areas[o.id]){change(o.id);return}if(o.id==='bia'){talked=true;update();dialog('BIA · SUA VIZINHA','Bem-vindo à cidade, Miguel!',`<p>“Você já tem um emprego. A aventura agora é equilibrar trabalho, estudo, dinheiro e descanso.”</p><p>“Na biblioteca dá para aprender sem comprar nada. Use seu caderno quando quiser uma direção.”</p>`,[{label:'Mostrar meu próximo passo',primary:true,action:journal},{label:'Continuar a conversa depois',action:close}]);return}if(o.id==='teacher'||o.id==='books'){dialog('DANIEL · BIBLIOTECA','Ferramentas para ir mais longe.',`<p>Uma preparação gratuita para sua rotina: organização de registros, atendimento e orçamento.</p>`,[{label:studied?'Revisar a atividade':'Estudar por uma hora',primary:true,action(){if(!useEnergy(15))return;studied=true;time=Math.min(1380,time+60);result('Você se preparou para o trabalho. O caderno indica seu próximo passo.')}}]);return}if(o.id==='boss'||o.id==='workdesk'){workShift();return}if(o.id==='leo'){dialog('LÉO · ENTREGADOR',errand?'Valeu pela ajuda!':'Uma entrega, dois caminhos.',`<p>${errand?'“Consegui chegar à biblioteca. Obrigado por ajudar!”':'“Preciso levar estes livros à biblioteca. O aplicativo oferece uma taxa para indicar o endereço, mas posso pedir informação. O que vale tentar?”'}</p>`,errand?[]:[{label:'Mostrar a biblioteca no mapa · gratuito',primary:true,action(){errand=true;result('Você ajudou Léo. Informação e cooperação também resolvem problemas sem gastar.')}},{label:'Conversar sobre o caminho',action(){result('Daniel fica na escola, no lado sul da praça. O caderno e o mapa mostram como chegar.','dialog')}}]);return}if(o.id==='seller'||o.id==='display'||o.id==='stylehost'){store();return}if(o.id==='cafehost'){dialog('CAIO · CAFÉ','Uma pausa no caminho.',`<p>Café e lanche · ${cashFmt(18)}. Ou aproveite um passeio gratuito no parque.</p>`,[{label:'Comprar lanche · R$ 18',primary:true,disabled:cash<18,action(){const s=engine.spend(18,'Lanche no café');pull(s);if(s.error){result(s.error,'warning');return}energy=Math.min(100,energy+20);time=Math.min(1380,time+30);result('Pausa feita: +20 de disposição. O lanche foi registrado como gasto extra.')}},{label:'Prefiro passear no parque',action:()=>navigate('park')}]);return}if(o.id==='parkhost'){dialog('BIA · LAZER','A vida também acontece na folga.',`<p>Um passeio gratuito recupera disposição. Nenhuma compra é necessária para aproveitar a cidade.</p>`,[{label:'Caminhar e conversar no parque',primary:true,action(){leisureDone=true;energy=Math.min(100,energy+30);time=Math.min(1380,time+60);result('Você respirou, conversou e recuperou disposição. +30, sem gastar.','rest')}}]);return}if(o.id==='bankhost'){phone();return}if(o.id==='bus'){dialog('TRANSPORTE','Para onde vamos?',`<p>Ônibus: R$ 5 por viagem. Caminhar é gratuito; o trajeto aparece no mapa.</p>`,[{label:'Ônibus até o trabalho · R$ 5',disabled:cash<5,action(){const s=engine.spend(5,'Ônibus');pull(s);if(!s.error){time=Math.min(1380,time+20);change('work')}}},{label:'Caminhar até o trabalho',primary:true,action:()=>navigate('work')}]);return}if(o.id==='bed'){sleep();return}if(o.id==='desk'){journal();return}}
function store(){if(!engine)return;if(financial.bill>0){invoiceGate(store);return}const category=area==='style'?'style':'tech',ids=districts[category],available=financial.goods.filter(p=>ids.includes(p.id)&&financial.available.includes(p.id));dialog(area==='style'?'NINA · MODA E CUIDADOS':'RAFA · TECNOLOGIA','Vitrine do mês, escolhas suas.',`<p>As ofertas seguem a vitrine mensal da v27.7. Comprar é opcional. Você pode adquirir vários itens, comparar pagamentos ou esperar o próximo mês.</p>`,[...available.map(p=>({label:p.name+' · '+cashFmt(p.price)+(p.eligible?'':' · já atendido'),disabled:!p.eligible,action:()=>offer(p)})),{label:'Ver todas as ofertas da cidade',action:catalog}]);}
function catalog(){dialog('COMÉRCIO DA CIDADE','Ofertas deste mês.',`<p>Necessidades e desejos da v27.7, com os mesmos preços e condições. O catálogo muda a cada mês.</p>`,financial.goods.filter(p=>financial.available.includes(p.id)).map(p=>({label:p.name+' · '+cashFmt(p.price),disabled:!p.eligible,action:()=>offer(p)})));}
function offer(p){const max=p.max;dialog('LOJA · '+p.name,'Escolha como pagar.',`<p>Preço: ${cashFmt(p.price)} · débito/Pix: <strong>${cashFmt(p.debit)}</strong>${p.debit<p.price?' · desconto de '+cashFmt(p.price-p.debit):''}.</p><label>Pagamento<select id="b-method"><option value="debit">Débito / Pix</option>${financial.month<8?'<option value="credit1">Crédito em 1x</option>':''}${max>=2&&financial.month<8?'<option value="card">Crédito parcelado</option>':''}</select></label><div id="b-plan" hidden><label>Parcelas<select id="b-installments">${Array.from({length:Math.max(0,max-1)},(_,i)=>'<option value="'+(i+2)+'">'+(i+2)+' parcelas</option>').join('')}</select></label><label>Entrada (R$)<input id="b-entry" type="number" min="0" step="100" value="0"></label></div><p id="b-quote" role="status"></p>`,[{label:'Revisar a compra',primary:true,action(){const plan=readPlan(),q=engine.quote(p.id,plan);if(q.error){root.querySelector('#b-quote').textContent=q.error;sound.cue('warning');return}dialog('CONFIRMAÇÃO',p.name,`<p>Total: <strong>${cashFmt(q.total)}</strong>.<br>Sai da conta agora: ${cashFmt(q.cashOut)}.<br>${plan.method==='card'?(q.n-1)+' × '+cashFmt(q.installment)+' + última de '+cashFmt(q.total-q.entry-(q.n-1)*q.installment)+' · entrada '+cashFmt(q.entry):plan.method==='credit1'?'Vence na próxima fatura.':'Pagamento à vista.'}</p><p>${q.interest?'Você está pagando '+cashFmt(q.interest)+' em juros.':'Sem juros.'}</p>`,[{label:'Confirmar compra',primary:true,action(){const s=engine.buy(p.id,plan.method,plan.installments,plan.entry);pull(s);celebrationUntil=performance.now()+2200;result(s.error||p.name+' adquirido! Consulte seus bens no celular.',s.error?'warning':'success')}},{label:'Voltar ao pagamento',action:()=>offer(p)}])}}]);function readPlan(){return{method:root.querySelector('#b-method').value,installments:Number(root.querySelector('#b-installments').value||2),entry:Number(root.querySelector('#b-entry').value)}}function quote(){const plan=readPlan(),q=engine.quote(p.id,plan);root.querySelector('#b-plan').hidden=plan.method!=='card';root.querySelector('#b-quote').textContent=q.error||('Total '+cashFmt(q.total)+' · '+(q.interest?'Você está pagando '+cashFmt(q.interest)+' em juros.':'Sem juros.')+(plan.method==='card'?' · '+(q.n-1)+' × '+cashFmt(q.installment)+' + última de '+cashFmt(q.total-q.entry-(q.n-1)*q.installment):''));}['b-method','b-installments','b-entry'].forEach(id=>root.querySelector('#'+id).addEventListener('input',quote));quote();}
function monthEnd(){if(!engine)return;dialog('FECHAMENTO · MÊS '+financial.month,financial.month===8?'Fim desta jornada.':'Olhe o caminho que você fez.',`<p>${shifts}/3 turnos representados · ${leisureDone?'lazer aproveitado':'lazer ainda disponível'}.</p><p>Conta: ${cashFmt(cash)} · reserva: ${cashFmt(reserve)} · fatura: ${cashFmt(financial.bill)} · dívida total: ${cashFmt(debt)}.</p><p>${financial.month===8?'O motor mantém as dívidas e os bens no balanço acima. Você pode continuar explorando este mês.':'A próxima virada lança salário, gastos fixos, reserva e encargos uma única vez.'}</p>`,financial.month===8?[]:[{label:'Pagar integral e virar o mês',primary:true,disabled:cash<financial.bill,action:()=>turn('invoiceFull')},{label:'Pagar mínimo e financiar saldo',disabled:financial.bill<=0||cash<financial.minimum,action:()=>turn('invoiceMinimum')},{label:'Não pagar e virar o mês',disabled:financial.bill<=0,action:()=>turn('invoiceNoPay')},{label:'Continuar vivendo este mês',action:close}]);}
function turn(choice){pull(engine.next(choice));day=0;time=540;energy=100;rested=false;shifts=0;leisureDone=false;worked=false;result('Mês '+financial.month+' começou. '+(financial.bill?'Fatura de '+cashFmt(financial.bill)+'. ':''),'month');}
